export class ErrorBoundary extends Component<{ children: ReactNode }, { hasError: boolean }> {
  state = { hasError: false };
  static getDerivedStateFromError() { return { hasError: true }; }
  render() {
    return this.state.hasError ? <button onClick={() => this.setState({ hasError: false })}>Retry</button> : this.props.children;
  }
}

import { createPortal } from 'react-dom';
export function Modal({ open, children }: { open: boolean; children: React.ReactNode }) {
  return open ? createPortal(<div role="dialog" aria-modal="true">{children}</div>, document.body) : null;
}

const ThemeCtx = createContext<{ dark: boolean; toggle: () => void } | null>(null);
export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [dark, setDark] = useState(false);
  const val = useMemo(() => ({ dark, toggle: () => setDark((d) => !d) }), [dark]);
  return <ThemeCtx.Provider value={val}>{children}</ThemeCtx.Provider>;
}

type Action = { type: 'answer'; id: string; idx: number } | { type: 'submit' };
export function examReducer(s: { answers: Record<string, number>; done: boolean }, a: Action) {
  if (a.type === 'answer') return { ...s, answers: { ...s.answers, [a.id]: a.idx } };
  return { ...s, done: true };
}

