export function Field({ label, hint }: { label: string; hint: string }) {
  const id = useId();
  return <><label htmlFor={id}>{label}</label><input id={id} aria-describedby={`${id}-h`} /><small id={`${id}-h`}>{hint}</small></>;
}

export function useInterval(cb: () => void, ms: number | null) {
  const ref = useRef(cb);
  useEffect(() => { ref.current = cb; }, [cb]);
  useEffect(() => {
    if (ms === null) return;
    const id = setInterval(() => ref.current(), ms);
    return () => clearInterval(id);
  }, [ms]);
}

export function useHydrated(): boolean {
