import type { ComponentPropsWithoutRef } from 'react';
interface BtnProps extends ComponentPropsWithoutRef<'button'> { variant?: 'primary' | 'secondary' }
export function Button({ variant = 'primary', type = 'button', className = '', ...rest }: BtnProps) {
  const base = variant === 'primary' ? 'bg-indigo-600 text-white' : 'border border-slate-300';
  return <button type={type} className={`rounded-lg px-4 py-2 ${base} ${className}`} {...rest} />;
}

export function safeHydrate<T extends object>(raw: string | null, defaults: T): T {
  if (!raw) return defaults;
  try {
    const parsed = JSON.parse(raw);
    return typeof parsed === 'object' && parsed !== null ? { ...defaults, ...parsed } : defaults;
  } catch { return defaults; }
}

