import { useImperativeHandle, useRef } from 'react';
export interface SearchHandle { focus: () => void }
export function SearchBox({ ref }: { ref?: React.Ref<SearchHandle> }) {
  const inputRef = useRef<HTMLInputElement>(null);
  useImperativeHandle(ref, () => ({ focus: () => inputRef.current?.focus() }), []);
  return <input ref={inputRef} aria-label="Search" />;
}

import { use } from 'react';
export function OptionalThemeBadge({ show }: { show: boolean }) {
  if (!show) return null;
  // Legal in React 19! Unlike useContext, use() can run after an early return.
  const theme = use(ThemeContext);
  return <span>{theme}</span>;
}

