}

export function formatStudyTime(minutes: number, locale = 'en-US'): string {
  const hours = Math.floor(minutes / 60);
  const mins = minutes % 60;
  const nf = new Intl.NumberFormat(locale);
  return hours > 0 ? `${nf.format(hours)}h ${nf.format(mins)}m` : `${nf.format(mins)}m`;
}

